const PICKS = ["DOPE", "SOL", "WIF", "ETH", "BONK"];
const DOPE_START = 0.00418;
const TARGET_BALANCE = 75_500;
const SESSION_START_SEC = 3 * 3600 + 61;
const MAX_PRICE_POINTS = 64;
const MAX_EQUITY_POINTS = 72;
const MAX_CANDLES = 38;

const ACTIVITY_POOL: ReadonlyArray<{ agent: AgentId; text: string; tone: Tone }> = [
