          <g className="cables" fill="none" strokeLinecap="round">
            {STATIONS.map((station, index) => (
              <g key={`cable-${station.id}`}>
                <path
                  d={`M ${530 + index * 6} 300 C ${530 + index * 6} ${station.y - 56}, ${station.x + 68} ${station.y - 84}, ${station.x + 68} ${station.y + 4}`}
                  stroke={station.accent}
                  strokeOpacity="0.24"
                  strokeWidth="1.6"
                  strokeDasharray="3 8"
                  className="cable-flow"
                />
                <circle cx={station.x + 68} cy={station.y + 4} r="2.3" fill={station.accent} opacity="0.55" />
              </g>
            ))}
            <path d="M 872 300 C 900 314, 930 340, 964 402" stroke="#ffd166" strokeOpacity="0.3" strokeWidth="1.6" strokeDasharray="3 8" className="cable-flow" />
          </g>

          <rect x="512" y="300" width="84" height="12" rx="2" fill="#1b0f24" stroke="#5b356c" />
          <text x="554" y="309" textAnchor="middle" className="room-micro" fill="#a98db7">
            ROUTER / 8 NODES
          </text>

          {STATIONS.map((station) => (
            <Workstation key={station.id} station={station} series={snapshot.priceSeries} active={snapshot.activeAgent === station.id} />
          ))}

          <Cage active={snapshot.activeAgent === "risk"} paused={paused} />
          <Vault active={snapshot.activeAgent === "risk"} />
          <ServerRack active={snapshot.activeAgent === "risk"} />
          <Ghost />

          <g transform="translate(18 508)" className="printer">
            <rect width="106" height="76" fill="#191020" stroke="#4b3159" />
            <rect x="8" y="8" width="90" height="17" fill="#0b0710" stroke="#2e1d39" />
            <text x="53" y="20" textAnchor="middle" className="room-decor-label" fill="#c4adcf">
              PAPER HANDS
            </text>
            <rect x="22" y="35" width="62" height="5" fill="#07040b" />
            <rect x="28" y="42" width="50" height="20" fill="#e9e2ea" />
            <line x1="33" x2="72" y1="48" y2="48" stroke="#a99fae" />
            <line x1="33" x2="66" y1="54" y2="54" stroke="#a99fae" />
            <circle cx="82" cy="62" r="5" fill="#ff3b9d" />
            <rect x="12" y="67" width="82" height="3" fill="#2d1a37" />
            <text x="53" y="73" textAnchor="middle" className="room-micro" fill="#776581">
              PRINTER JAMMED
            </text>
          </g>

          <Plant x={136} y={520} scale={0.92} />
          <Plant x={1130} y={524} scale={0.8} />
          <Plant x={32} y={432} scale={0.7} />

          <g transform="translate(1018 500)" className="fan">
            <rect x="14" y="60" width="44" height="8" fill="#2b1835" />
            <rect x="29" y="34" width="14" height="28" fill="#23142c" />
            <circle cx="36" cy="32" r="29" fill="#0d0813" stroke="#4b3357" strokeWidth="2" />
            <g className="fan-blades">
              <rect x="33" y="8" width="6" height="20" rx="2" fill="#6d577b" />
              <rect x="33" y="36" width="6" height="20" rx="2" fill="#6d577b" />
              <rect x="12" y="29" width="20" height="6" rx="2" fill="#584565" />
              <rect x="40" y="29" width="20" height="6" rx="2" fill="#584565" />
              <circle cx="36" cy="32" r="5" fill="#ff3b9d" />
            </g>
            <circle cx="36" cy="32" r="30" fill="none" stroke="#3a2746" strokeDasharray="2 5" />
            <text x="36" y="78" textAnchor="middle" className="room-micro" fill="#786487">
              WHALE RADAR
            </text>
          </g>

          <Bubble x={746} y={350} width={154} text={'"will he rekt?"'} tone="#ff5d8f" />
          <Bubble x={936} y={420} width={126} text={'"gm, size it"'} tone="#7ff7b2" />

          <g transform="translate(610 336)">
            <rect width="126" height="15" fill="#0b0710" stroke="#392446" opacity="0.85" />
            <circle cx="9" cy="7.5" r="2.5" fill={paused ? "#ffd166" : "#7ff7b2"} />
            <text x="18" y="10" className="room-micro" fill="#a98db7">
              {paused ? "SIM HELD" : latest ? latest.time : "SIM LIVE"}
            </text>
          </g>

          <rect x="14" y="14" width="1172" height="572" rx="10" fill="none" stroke="#3d2050" strokeWidth="2" />
          <rect x="21" y="21" width="1158" height="558" rx="7" fill="none" stroke="#ff3b9d" strokeOpacity="0.12" />
          <g opacity="0.5">
            <rect x="14" y="14" width="20" height="3" fill="#ff3b9d" />
            <rect x="14" y="14" width="3" height="20" fill="#ff3b9d" />
            <rect x="1166" y="583" width="20" height="3" fill="#ff3b9d" />
            <rect x="1183" y="566" width="3" height="20" fill="#ff3b9d" />
          </g>
        </svg>

        {paused ? <div className="room-held-badge" role="status">SIMULATION HELD // RESUME TO STREAM</div> : null}
        <div className="room-stamp" aria-hidden="true">
          <span>LIVE FEED</span>
          <strong>{snapshot.sessionTime}</strong>
        </div>
      </div>

      <div className="room-bottom">
        <div className="room-activity" aria-label="Latest agent activity">
          {snapshot.activity.slice(0, 2).map((item) => (
            <div key={item.id} className={`room-activity__item tone-text-${item.tone}`}>
              <span className="activity-agent">{item.agent.toUpperCase()}</span>
              <p>{item.text}</p>
              <time>{item.time}</time>
            </div>
          ))}
        </div>
        <div className="room-telemetry">
          <span>LAT <b>{snapshot.latency}ms</b></span>
          <span>GAS <b>{snapshot.gas.toFixed(3)}</b></span>
          <span>FILLS <b>{snapshot.fills.toLocaleString("en-US")}</b></span>
          <span>HOLDERS <b>{snapshot.holders}</b></span>
        </div>
      </div>
    </figure>
  );
}

:root {
  --bg: #07060b;
  --bg-raised: #0d0914;
  --panel: #0e0a15;
  --panel-2: #120d1a;
  --line: #2e1d3a;
  --line-soft: #24162e;
  --pink: #ff3b9d;
  --pink-soft: #ff9ec7;
  --pink-deep: #b31d68;
  --mint: #7ff7b2;
  --mint-soft: #c4ffdc;
  --mint-deep: #2c9c6a;
  --amber: #ffd166;
  --cyan: #6ed6ff;
  --red: #ff5d6c;
  --text: #f4ecf7;
  --muted: #a28fac;
  --faint: #6d5b79;
  --mono: "IBM Plex Mono", "SFMono-Regular", Consolas, monospace;
  --pixel: "Silkscreen", "IBM Plex Mono", monospace;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  color-scheme: dark;
  background: var(--bg);
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  background:
    radial-gradient(55% 34% at 9% -8%, rgba(255, 59, 157, 0.14), transparent 68%),
    radial-gradient(48% 30% at 96% 4%, rgba(110, 214, 255, 0.08), transparent 62%),
    radial-gradient(60% 40% at 50% 105%, rgba(127, 247, 178, 0.045), transparent 65%),
    var(--bg);
  color: var(--text);
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.45;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 90;
  pointer-events: none;
  background: repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.018) 0, rgba(255, 255, 255, 0.018) 1px, transparent 1px, transparent 3px);
  opacity: 0.7;
}

::selection {
  background: var(--pink);
  color: #10070d;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #0a0710;
}

::-webkit-scrollbar-thumb {
  background: #3a2547;
  border: 2px solid #0a0710;
}

a {
  color: var(--mint);
}

button {
  font-family: inherit;
}

button:focus-visible {
  outline: 2px solid var(--mint);
  outline-offset: 2px;
}

.app-shell {
  position: relative;
  width: 100%;
  max-width: 1560px;
  margin: 0 auto;
  padding: 20px clamp(14px, 2.3vw, 34px) 30px;
  isolation: isolate;
}

.ambient-grid {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.022) 1px, transparent 1px);
  background-size: 54px 54px;
  -webkit-mask-image: radial-gradient(circle at 50% 0%, #000 0%, transparent 74%);
  mask-image: radial-gradient(circle at 50% 0%, #000 0%, transparent 74%);
}

.tone-mint {
  color: var(--mint);
}

.tone-pink {
  color: var(--pink-soft);
}

.tone-amber {
  color: var(--amber);
}

.tone-cyan {
  color: var(--cyan);
}

.tone-red {
  color: var(--red);
}

/* ---------------- top bar ---------------- */

.topbar {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(12px, 1.6vw, 24px);
  padding: 12px clamp(12px, 1.3vw, 18px);
  border: 1px solid #3d2549;
  background:
    linear-gradient(90deg, rgba(255, 59, 157, 0.08), transparent 22%, transparent 78%, rgba(255, 59, 157, 0.07)),
    linear-gradient(180deg, #140d1c, #0b0711);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

.topbar::before {
  content: "";
  position: absolute;
  left: -1px;
  top: 8px;
  bottom: 8px;
  width: 3px;
  background: var(--pink);
  box-shadow: 0 0 14px rgba(255, 59, 157, 0.8);
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--pink);
  background: #180b1c;
  color: var(--pink);
  box-shadow: inset 0 0 18px rgba(255, 59, 157, 0.16), 0 0 18px rgba(255, 59, 157, 0.08);
}

.brand-mark__svg {
  width: 28px;
  height: 28px;
  display: block;
  filter: drop-shadow(0 0 6px rgba(255, 59, 157, 0.5));
}

.brand-copy {
  min-width: 0;
}

.brand-copy h1 {
  margin: 0;
  font-family: var(--pixel);
  font-size: clamp(14px, 1.35vw, 20px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.2px;
  color: #fbf4fc;
  white-space: nowrap;
}

.brand-copy h1 span {
  color: var(--pink);
}

.brand-copy p {
  margin: 4px 0 0;
  font-size: 7.5px;
  line-height: 1.3;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #8f7a9c;
  white-space: nowrap;
}

.brand-live {
  color: var(--mint);
}

.tape {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 4px 11px;
  min-width: 0;
  padding: 6px 16px;
  border-left: 1px dashed #3a2647;
  border-right: 1px dashed #3a2647;
  color: #8f7a9b;
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.55px;
  text-transform: uppercase;
}

.tape-pair {
  color: var(--cyan);
}

.tape-price {
  color: #f7eff9;
  font-weight: 600;
}

.tape-up {
  color: var(--mint);
}

.tape-down {
  color: var(--red);
}

.tape-sep {
  color: #4f3b5c;
}

.tape-latency {
  color: #6a5777;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.3vw, 18px);
  min-width: 0;
}

.bankroll {
  width: clamp(108px, 10vw, 154px);
  min-width: 0;
}

.bankroll-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  margin-bottom: 4px;
  font-size: 7px;
  letter-spacing: 1.1px;
  color: #786585;
}

.bankroll-label b {
  color: var(--mint);
  font-weight: 500;
}

.bankroll-track {
  position: relative;
  height: 7px;
  border: 1px solid #4c2d5e;
  background: repeating-linear-gradient(90deg, #1a1022 0, #1a1022 4px, #120b18 4px, #120b18 6px);
  overflow: hidden;
}

.bankroll-track span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #862454, var(--pink));
  box-shadow: 0 0 10px rgba(255, 59, 157, 0.55);
}

.bankroll-track i {
  position: absolute;
  top: -2px;
  bottom: -2px;
  left: 75.2%;
  width: 2px;
  background: #ffe3f2;
  opacity: 0.8;
}

.session {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-left: clamp(8px, 1vw, 14px);
  border-left: 1px dashed #3a2647;
  white-space: nowrap;
}

.session span {
  font-size: 7.5px;
  letter-spacing: 1px;
  color: #887494;
}

.session span em {
  font-style: normal;
  color: #5f4c6c;
}

.session strong {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.6px;
  color: var(--mint);
}

.controls {
  display: flex;
  gap: 6px;
  flex: 0 0 auto;
}

.btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 11px;
  border: 1px solid #51345f;
  background: #180f20;
  color: #cab7d4;
  font-family: var(--pixel);
  font-size: 8px;
  line-height: 1;
  letter-spacing: 0.8px;
  cursor: pointer;
  transition: border-color 0.16s ease, color 0.16s ease, background 0.16s ease, transform 0.16s ease;
}

.btn:hover {
  border-color: var(--pink);
  color: #ffffff;
  transform: translateY(-1px);
}

.btn-hot {
  border-color: #b82a70;
  background: linear-gradient(180deg, #8e1f56, #551032);
  color: #fff4fa;
  box-shadow: 0 0 14px rgba(255, 59, 157, 0.14);
}

.btn-hot:hover {
  background: linear-gradient(180deg, #ad2569, #6d1542);
}

.btn-glyph {
  display: inline-block;
  flex: 0 0 auto;
  color: currentColor;
}

.btn-glyph--pause {
  width: 8px;
  height: 9px;
  border-left: 3px solid currentColor;
  border-right: 3px solid currentColor;
}

.btn-glyph--play {
  width: 0;
  height: 0;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
  border-left: 6px solid currentColor;
}

/* ---------------- section headers ---------------- */

.dashboard {
  display: block;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin: 24px 0 10px;
}

.eyebrow {
  display: block;
  margin-bottom: 4px;
  font-size: 7.5px;
  letter-spacing: 2px;
  color: #9f7daf;
}

.section-title h2 {
  margin: 0;
  font-family: var(--pixel);
  font-size: clamp(13px, 1.25vw, 17px);
  font-weight: 400;
  letter-spacing: 0.4px;
  color: #f6edf8;
}

.section-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  font-size: 8px;
  letter-spacing: 1px;
  color: #887594;
  white-space: nowrap;
}

.status-dot {
  width: 6px;
  height: 6px;
  background: var(--mint);
  box-shadow: 0 0 9px var(--mint);
  animation: status-pulse 2s ease-in-out infinite;
}

.status-dot--held {
  background: var(--amber);
  box-shadow: 0 0 9px var(--amber);
  animation: none;
}

.meta-divider {
  color: #4f3b5c;
}

/* ---------------- agent grid ---------------- */

.agent-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.accent-pink {
  --accent: var(--pink);
  --accent-glow: rgba(255, 59, 157, 0.3);
}

.accent-mint {
  --accent: var(--mint);
  --accent-glow: rgba(127, 247, 178, 0.24);
}

.accent-cyan {
  --accent: var(--cyan);
  --accent-glow: rgba(110, 214, 255, 0.24);
}

.accent-amber {
  --accent: var(--amber);
  --accent-glow: rgba(255, 209, 102, 0.24);
}

.accent-red {
  --accent: var(--red);
  --accent-glow: rgba(255, 93, 108, 0.26);
}

.value-tone-mint {
  --value: var(--mint);
}

.value-tone-pink {
  --value: #ff9ec7;
}

.value-tone-amber {
  --value: var(--amber);
}

.value-tone-cyan {
  --value: var(--cyan);
}

.value-tone-red {
  --value: var(--red);
}

.agent-card {
  position: relative;
  min-width: 0;
  padding: 10px 12px 8px;
  border: 1px solid #332140;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.027), transparent 32%),
    linear-gradient(180deg, #110c18, #0b0810);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.028);
  transition: border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

.agent-card::before,
.agent-card::after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  pointer-events: none;
  opacity: 0.48;
  transition: opacity 0.18s ease;
}

.agent-card::before {
  top: -1px;
  left: -1px;
  border-top: 1px solid var(--accent);
  border-left: 1px solid var(--accent);
}

.agent-card::after {
  right: -1px;
  bottom: -1px;
  border-right: 1px solid var(--accent);
  border-bottom: 1px solid var(--accent);
}

.agent-card:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.32), inset 0 0 22px rgba(255, 255, 255, 0.018);
}

.agent-card.is-active {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent-glow), 0 0 26px var(--accent-glow), inset 0 0 24px rgba(255, 255, 255, 0.025);
}

.agent-card.is-active::before,
.agent-card.is-active::after {
  opacity: 1;
}

.agent-card__head {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding-bottom: 8px;
  border-bottom: 1px solid #2a1a35;
}

.agent-icon {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid currentColor;
  color: var(--accent);
  background: #190f21;
  box-shadow: inset 0 0 10px var(--accent-glow);
}

.agent-icon svg {
  width: 15px;
  height: 15px;
  display: block;
}

.agent-name {
  min-width: 0;
  flex: 1;
}

.agent-name h3 {
  margin: 0;
  font-family: var(--pixel);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #f6edf8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agent-name p {
  margin: 3px 0 0;
  font-size: 7px;
  letter-spacing: 0.55px;
  text-transform: uppercase;
  color: #82708e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agent-state {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 12px;
  flex: 0 0 auto;
}

.agent-state i {
  display: block;
  width: 2px;
  background: var(--accent);
  opacity: 0.22;
}

.agent-state i:nth-child(1) {
  height: 4px;
}

.agent-state i:nth-child(2) {
  height: 8px;
}

.agent-state i:nth-child(3) {
  height: 12px;
}

.agent-card.is-active .agent-state i {
  animation: equalize 0.9s steps(3, end) infinite;
}

.agent-card.is-active .agent-state i:nth-child(2) {
  animation-delay: 0.16s;
}

.agent-card.is-active .agent-state i:nth-child(3) {
  animation-delay: 0.32s;
}

.agent-card__body {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 0 8px;
  min-height: 65px;
}

.agent-copy {
  flex: 1;
  min-width: 0;
}

.agent-headline {
  margin: 0;
  font-size: 9.5px;
  line-height: 1.35;
  font-weight: 500;
  letter-spacing: 0.15px;
  color: #ded2e5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.spark {
  display: block;
  width: 100%;
  height: 26px;
  margin-top: 7px;
  overflow: visible;
}

.spark--mint {
  color: var(--mint);
}

.spark--pink {
  color: var(--pink);
}

.spark--amber {
  color: var(--amber);
}

.spark--cyan {
  color: var(--cyan);
}

.spark--red {
  color: var(--red);
}

.agent-value {
  flex: 0 0 auto;
  max-width: 52%;
  padding-top: 1px;
  font-family: var(--pixel);
  font-size: clamp(16px, 1.55vw, 21px);
  line-height: 1;
  letter-spacing: 0.2px;
  color: var(--value, var(--accent));
  text-shadow: 0 0 18px var(--accent-glow);
  white-space: nowrap;
}

.agent-progress {
  height: 4px;
  background: #25162f;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

.agent-progress span {
  display: block;
  height: 100%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent-glow);
  transition: width 0.6s cubic-bezier(0.2, 0.7, 0.2, 1);
}

.agent-card__foot {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding-top: 7px;
  font-size: 7px;
  letter-spacing: 0.45px;
  color: #705d7d;
}

.agent-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
  color: #8f7c9b;
  text-transform: uppercase;
  white-space: nowrap;
}

.agent-status i {
  width: 4px;
  height: 4px;
  display: block;
  background: #5e4b6b;
}

.agent-status--active {
  color: var(--accent);
}

.agent-status--active i {
  background: var(--accent);
  box-shadow: 0 0 6px var(--accent);
}

.agent-sub {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.refresh-glyph {
  width: 11px;
  height: 11px;
  flex: 0 0 auto;
  opacity: 0.5;
}

.agent-card.is-active .refresh-glyph {
  color: var(--accent);
  opacity: 0.9;
  animation: spin 3s linear infinite;
}

/* ---------------- pixel room ---------------- */

.room-card {
  position: relative;
  margin: 16px 0 0;
  border: 1px solid #c2266f;
  background: #0a0710;
  box-shadow:
    0 0 0 1px rgba(255, 59, 157, 0.09),
    0 24px 70px rgba(0, 0, 0, 0.5),
    0 0 44px rgba(255, 59, 157, 0.07);
}

.room-card::before,
.room-card::after {
  content: "";
  position: absolute;
  z-index: 3;
  width: 16px;
  height: 16px;
  pointer-events: none;
}

.room-card::before {
  top: -1px;
  left: -1px;
  border-top: 2px solid #ff72b5;
  border-left: 2px solid #ff72b5;
}

.room-card::after {
  right: -1px;
  bottom: -1px;
  border-right: 2px solid #ff72b5;
  border-bottom: 2px solid #ff72b5;
}

.room-chrome {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 18px;
  min-width: 0;
  padding: 9px 13px;
  border-bottom: 1px solid #642349;
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.02) 0, rgba(255, 255, 255, 0.02) 1px, transparent 1px, transparent 5px),
    linear-gradient(90deg, #200d22, #100a16 45%, #210d23);
}

.room-title-wrap {
  flex: 0 0 auto;
}

.room-kicker {
  display: block;
  margin-bottom: 3px;
  font-size: 7px;
  letter-spacing: 1.4px;
  color: #ae8ab9;
}

.room-title-wrap h2 {
  margin: 0;
  font-family: var(--pixel);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.8px;
  color: #fff3f9;
  white-space: nowrap;
}

.room-tape {
  display: flex;
  align-items: center;
  gap: 7px 14px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-size: 7.5px;
  letter-spacing: 0.65px;
  color: #947c9f;
}

.room-tape span {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  flex: 0 0 auto;
}

.room-tape span + span {
  padding-left: 13px;
  border-left: 1px solid #3a2145;
}

.room-tape b {
  color: #dfd0e5;
  font-weight: 500;
}

.room-tape .tone-mint {
  color: var(--mint);
}

.room-tape .tone-red {
  color: var(--red);
}

.room-tape-active {
  margin-left: auto;
  color: #ffb8d7 !important;
}

.room-tape-active b {
  color: var(--pink) !important;
}

.room-controls {
  display: flex;
  gap: 5px;
  flex: 0 0 auto;
}

.chip-button {
  appearance: none;
  min-height: 25px;
  padding: 0 8px;
  border: 1px solid #6a2b50;
  background: #241020;
  color: #ffc5dd;
  font-family: var(--pixel);
  font-size: 7px;
  letter-spacing: 0.65px;
  cursor: pointer;
  transition: background 0.16s ease, border-color 0.16s ease, color 0.16s ease;
}

.chip-button:hover {
  border-color: var(--pink);
  background: #38152f;
  color: #fff;
}

.chip-button--quiet {
  border-color: #443051;
  background: #160f1d;
  color: #a28dae;
}

.room-viewport {
  position: relative;
  width: 100%;
  aspect-ratio: 1200 / 600;
  min-height: 260px;
  overflow: hidden;
  background: #08050d;
}

.room-svg {
  display: block;
  width: 100%;
  height: 100%;
}

.room-svg text {
  font-family: var(--mono);
}

.room-screen-title {
  font-family: var(--pixel) !important;
  font-size: 8px;
  letter-spacing: 0.7px;
}

.room-axis {
  font-size: 6px;
  fill: #6b8075;
  letter-spacing: 0.2px;
}

.room-price-tag {
  font-family: var(--pixel) !important;
  font-size: 7px;
  fill: #1b0812;
  font-weight: 700;
}

.room-screen-foot {
  font-size: 7px;
  fill: #c7bacd;
  letter-spacing: 0.25px;
}

.room-tone-mint {
  fill: var(--mint);
}

.room-monitor-label {
  font-family: var(--pixel) !important;
  font-size: 5.5px;
  letter-spacing: 0.3px;
  opacity: 0.78;
}

.room-tag {
  font-family: var(--pixel) !important;
  font-size: 7px;
  font-weight: 400;
  letter-spacing: 0.5px;
}

.room-decor-label {
  font-family: var(--pixel) !important;
  font-size: 6.2px;
  letter-spacing: 0.25px;
}

.room-micro {
  font-size: 6px;
  fill: #8b7798;
  letter-spacing: 0.1px;
}

.room-logo-text {
  font-family: var(--pixel) !important;
  font-size: 16px;
  letter-spacing: 2px;
}

.bubble-text {
  font-size: 7.5px;
  letter-spacing: 0.2px;
}

.screen-sweep {
  animation: screen-sweep 5.5s linear infinite;
}

.cable-flow {
  animation: cable-dash 2.2s linear infinite;
}

.rack-led {
  animation: led-blink 1.5s steps(2, end) infinite;
}

.fan-blades {
  transform-box: fill-box;
  transform-origin: center;
  animation: spin 4s linear infinite;
}

.agent-ping circle:first-child {
  animation: ping 1.5s ease-out infinite;
}

.station--live .station-bob {
  animation: station-bob 1.7s steps(2, end) infinite;
}

.station--live .station-screen {
  filter: drop-shadow(0 0 4px currentColor);
}

.station--live .room-tag {
  filter: drop-shadow(0 0 4px currentColor);
}

.cage--live {
  filter: drop-shadow(0 0 8px rgba(255, 59, 157, 0.32));
}

.vault--live,
.rack--live {
  filter: drop-shadow(0 0 7px rgba(255, 93, 108, 0.3));
}

.room-step-active .station-bob {
  animation: none;
}

.room-held-badge {
  position: absolute;
  top: 12px;
  left: 50%;
  z-index: 4;
  transform: translateX(-50%);
  padding: 6px 10px;
  border: 1px solid #ff86bb;
  background: rgba(61, 12, 38, 0.92);
  color: #ffd4e6;
  font-family: var(--pixel);
  font-size: 8px;
  letter-spacing: 0.8px;
  white-space: nowrap;
  box-shadow: 0 0 20px rgba(255, 59, 157, 0.25);
}

.room-stamp {
  position: absolute;
  right: 12px;
  bottom: 10px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  padding: 4px 6px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(8, 5, 13, 0.66);
  color: #9c86a7;
  font-size: 6px;
  letter-spacing: 0.7px;
  backdrop-filter: blur(2px);
}

.room-stamp strong {
  color: var(--mint);
  font-size: 7.5px;
  font-weight: 500;
}

.room-bottom {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 8px 12px;
  border-top: 1px solid #3d2148;
  background: #0c0812;
}

.room-activity {
  display: flex;
  align-items: center;
  gap: 22px;
  min-width: 0;
}

.room-activity__item {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  flex: 1;
  font-size: 8px;
  color: #b8a6c3;
}

.activity-agent {
  flex: 0 0 auto;
  padding: 2px 4px;
  border: 1px solid currentColor;
  color: var(--feed, var(--pink));
  font-family: var(--pixel);
  font-size: 6.5px;
  letter-spacing: 0.3px;
  white-space: nowrap;
}

.room-activity__item p {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.room-activity__item time {
  margin-left: auto;
  flex: 0 0 auto;
  color: #5f4c6b;
  font-size: 6.5px;
}

.tone-text-pink {
  --feed: var(--pink-soft);
}

.tone-text-mint {
  --feed: var(--mint);
}

.tone-text-amber {
  --feed: var(--amber);
}

.tone-text-cyan {
  --feed: var(--cyan);
}

.tone-text-red {
  --feed: var(--red);
}

.tone-text-pink .activity-agent {
  color: var(--pink-soft);
}

.tone-text-mint .activity-agent {
  color: var(--mint);
}

.tone-text-amber .activity-agent {
  color: var(--amber);
}

.tone-text-cyan .activity-agent {
  color: var(--cyan);
}

.tone-text-red .activity-agent {
  color: var(--red);
}

.room-telemetry {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 0 0 auto;
  font-size: 7px;
  letter-spacing: 0.45px;
  color: #6f5c7c;
  white-space: nowrap;
}

.room-telemetry b {
  margin-left: 2px;
  color: #c7b5d1;
  font-weight: 500;
}

/* ---------------- shared panels ---------------- */

.lower-grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 16px;
}

.panel {
  position: relative;
  min-width: 0;
  border: 1px solid #33213f;
  background: linear-gradient(180deg, #0e0a15, #09060e);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.panel-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 12px 15px;
  border-bottom: 1px solid #2a1a35;
}

.panel-heading {
  min-width: 0;
}

.panel-kicker {
  display: block;
  margin-bottom: 5px;
  color: #8d7899;
  font-size: 7px;
  letter-spacing: 1.5px;
}

.panel-kicker--pink {
  color: var(--pink);
}

.panel-head h2 {
  margin: 0;
  font-family: var(--pixel);
  font-size: clamp(11px, 1.1vw, 14px);
  font-weight: 400;
  letter-spacing: 0.4px;
  color: #f6eef9;
}

/* ---------------- equity panel ---------------- */

.equity-head {
  align-items: center;
}

.equity-readout {
  display: flex;
  align-items: center;
  gap: clamp(9px, 1.3vw, 18px);
  flex-wrap: wrap;
  justify-content: flex-end;
  margin-left: auto;
}

.pnl-chip {
  padding: 4px 7px;
  border: 1px solid #2d7459;
  background: rgba(29, 84, 60, 0.2);
  color: var(--mint);
  font-size: 7.5px;
  letter-spacing: 0.35px;
  white-space: nowrap;
}

.pnl-chip span {
  color: #9ad4b8;
}

.pnl-down {
  border-color: #773443;
  background: rgba(94, 30, 44, 0.18);
  color: var(--red);
}

.pnl-down span {
  color: #e3a3ad;
}

.equity-balance {
  display: flex;
  align-items: baseline;
  gap: 1px;
  font-family: var(--pixel);
  font-size: clamp(24px, 2.9vw, 37px);
  line-height: 0.95;
  letter-spacing: -0.5px;
  color: #f8f2fa;
  text-shadow: 0 0 24px rgba(127, 247, 178, 0.1);
  white-space: nowrap;
}

.equity-balance > span:first-child {
  margin-right: 2px;
  color: #7c6a88;
  font-size: 0.5em;
}

.equity-balance .cents {
  color: var(--mint);
  font-size: 0.58em;
  letter-spacing: 0;
}

.chart-wrap {
  position: relative;
  padding: 4px 6px 0;
}

.equity-chart {
  display: block;
  width: 100%;
  height: clamp(185px, 20vw, 255px);
  touch-action: none;
  cursor: crosshair;
}

.chart-grid {
  stroke: #2a1b34;
  stroke-width: 0.8;
  stroke-dasharray: 2 6;
}

.chart-axis-label {
  fill: #6c5979;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.2px;
}

.equity-line {
  fill: none;
  stroke: rgba(127, 247, 178, 0.55);
  stroke-width: 3.5;
}

.equity-line--core {
  stroke: #a5ffd0;
  stroke-width: 1.5;
}

.chart-level {
  stroke: rgba(127, 247, 178, 0.22);
  stroke-width: 0.8;
  stroke-dasharray: 4 6;
}

.equity-pulse {
  fill: none;
  stroke: rgba(127, 247, 178, 0.55);
  stroke-width: 1;
  animation: pnl-pulse 2.2s ease-out infinite;
}

.equity-dot {
  fill: var(--mint);
  filter: drop-shadow(0 0 5px var(--mint));
}

.volume-bar {
  opacity: 0.48;
}

.volume-up {
  fill: var(--mint-deep);
}

.volume-down {
  fill: #8f2e50;
}

.chart-crosshair {
  stroke: rgba(255, 59, 157, 0.7);
  stroke-width: 0.8;
  stroke-dasharray: 3 5;
}

.hover-dot {
  fill: var(--pink);
  stroke: #1a0912;
  stroke-width: 1.2;
}

.chart-tooltip {
  position: absolute;
  top: 8px;
  z-index: 3;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 112px;
  padding: 6px 8px;
  border: 1px solid #9e2c66;
  background: rgba(12, 7, 16, 0.94);
  box-shadow: 0 0 20px rgba(255, 59, 157, 0.12);
  pointer-events: none;
}

.chart-tooltip span {
  color: #8f7a9b;
  font-size: 6.5px;
  letter-spacing: 0.6px;
}

.chart-tooltip strong {
  color: #fff4fa;
  font-family: var(--pixel);
  font-size: 11px;
  font-weight: 400;
}

.equity-foot {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 8px 15px 9px;
  border-top: 1px solid #291a33;
  color: #776482;
  font-size: 7px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.equity-foot b {
  color: #d6c7de;
  font-weight: 500;
}

.legend-dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  margin-right: 4px;
  vertical-align: 1px;
}

.legend-dot--mint {
  background: var(--mint);
}

.legend-dot--pink {
  background: #8f2e50;
}

.equity-foot__hint {
  margin-left: auto;
  color: #52425e;
}

.lower-split {
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(292px, 1fr);
  gap: 12px;
  align-items: stretch;
}

/* ---------------- analysis panel ---------------- */

.analysis-panel {
  display: flex;
  flex-direction: column;
}

.analysis-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  color: #806c8c;
  font-size: 7px;
  letter-spacing: 0.55px;
}

.analysis-meta b {
  margin-left: 3px;
  color: #d6c7de;
  font-weight: 500;
}

.signal {
  display: inline-block;
  margin-left: 7px;
  padding: 2px 5px;
  border: 1px solid currentColor;
  font-family: var(--mono);
  font-size: 6.5px;
  font-weight: 500;
  letter-spacing: 0.6px;
  vertical-align: 2px;
}

.signal--long {
  color: var(--mint);
}

.signal--short {
  color: var(--red);
}

.analysis-body {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(215px, 0.85fr);
  flex: 1;
  min-width: 0;
}

.analysis-chart {
  min-width: 0;
  padding: 4px 4px 0;
  border-right: 1px solid #291a34;
}

.candle-chart {
  display: block;
  width: 100%;
  height: clamp(220px, 22vw, 285px);
}

.chart-empty {
  display: grid;
  place-items: center;
  height: 240px;
  color: var(--faint);
  font-size: 8px;
  letter-spacing: 1px;
}

.wick {
  stroke-width: 1;
}

.wick-up {
  stroke: #61e5a0;
}

.wick-down {
  stroke: #ff4f86;
}

.candle-up {
  fill: #61e5a0;
}

.candle-down {
  fill: #ff4f86;
}

.candle-volume--up {
  fill: rgba(97, 229, 160, 0.3);
}

.candle-volume--down {
  fill: rgba(255, 79, 134, 0.28);
}

.average-line {
  fill: none;
  stroke: rgba(255, 209, 102, 0.82);
  stroke-width: 1.1;
}

.last-price-line {
  stroke: rgba(255, 59, 157, 0.48);
  stroke-width: 0.8;
  stroke-dasharray: 3 4;
}

.last-price-tag {
  fill: var(--pink);
}

.last-price-text {
  fill: #1b0710;
  font-family: var(--pixel);
  font-size: 6.5px;
}

.analysis-side {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  padding: 8px 11px 9px;
}

.book-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  padding-bottom: 5px;
  border-bottom: 1px dashed #31213c;
  color: #8f7a9b;
  font-size: 6.8px;
  letter-spacing: 0.55px;
}

.book-rows {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.book-row {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 6px;
  overflow: hidden;
  border: 1px solid #2c1d37;
  background: #0b0710;
  color: #8e7a9a;
  font-size: 6.5px;
  letter-spacing: 0.4px;
}

.book-row b {
  position: relative;
  z-index: 1;
  font-size: 8px;
  font-weight: 500;
}

.book-row i {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  opacity: 0.18;
}

.book-row--ask b {
  color: #ffafcd;
}

.book-row--ask i {
  background: var(--pink);
}

.book-row--bid b {
  color: #b9ffd8;
}

.book-row--bid i {
  background: var(--mint);
}

.side-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: #2a1933;
  border: 1px solid #2a1933;
}

.side-grid > div {
  min-width: 0;
  padding: 5px 6px;
  background: #0c0812;
}

.side-grid span {
  display: block;
  margin-bottom: 2px;
  color: #675474;
  font-size: 6px;
  letter-spacing: 0.4px;
}

.side-grid b {
  display: block;
  overflow: hidden;
  color: #d8c9df;
  font-size: 8px;
  font-weight: 500;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.analysis-note {
  margin: 0;
  padding-left: 7px;
  border-left: 2px solid var(--pink);
  color: #a894b5;
  font-size: 7.2px;
  line-height: 1.5;
  min-height: 24px;
}

.caret {
  color: var(--pink);
}

/* ---------------- thresholds ---------------- */

.threshold-panel {
  display: flex;
  flex-direction: column;
}

.threshold-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 11px;
  border-bottom: 1px dashed #352140;
  background: linear-gradient(180deg, #140d1c, #0d0813);
}

.traffic-lights {
  display: flex;
  gap: 3px;
  flex: 0 0 auto;
}

.tl {
  width: 5px;
  height: 5px;
  display: block;
  border: 1px solid #000;
}

.tl--red {
  background: #ff5d6c;
}

.tl--amber {
  background: var(--amber);
}

.tl--mint {
  background: var(--mint);
}

