  text-transform: uppercase;
}

/* ---------------- motion ---------------- */

@keyframes status-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

@keyframes equalize {
  0% {
    opacity: 0.3;
    transform: scaleY(0.55);
  }
  100% {
    opacity: 1;
    transform: scaleY(1);
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes cable-dash {
  to {
    stroke-dashoffset: -44;
  }
}

@keyframes led-blink {
  0%,
  45% {
    opacity: 1;
  }
  46%,
  100% {
    opacity: 0.25;
  }
}

@keyframes screen-sweep {
  0% {
    transform: translateY(0);
    opacity: 0;
  }
  15% {
    opacity: 1;
  }
  82% {
    transform: translateY(140px);
    opacity: 0.3;
  }
  100% {
    transform: translateY(150px);
    opacity: 0;
  }
}

@keyframes station-bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-2px);
  }
}

@keyframes ping {
  0% {
    opacity: 0.22;
    transform: scale(0.7);
  }
  55% {
    opacity: 0.75;
    transform: scale(1.2);
  }
  100% {
    opacity: 0;
    transform: scale(1.7);
  }
}

@keyframes pnl-pulse {
  0% {
    opacity: 0.6;
    transform: scale(0.8);
    transform-origin: center;
  }
  100% {
    opacity: 0;
    transform: scale(2);
    transform-origin: center;
  }
}

